div.t-attf-class:
x-small py-1 px-2 rounded-1 border-start border-3 #{
                                            record.committee_decision.raw_value == 'direct_sale' ? 'border-success text-white bg-success' : 
                                            record.committee_decision.raw_value == 'auction' ? 'border-warning text-dark bg-warning' : 
                                            'border-danger text-white bg-danger'}

xpath.attribute:
[
                        ('res_model', '=', 'entries'),
                        ('project_stage_selection', 'not in',
                            [] if (has_data_completion or project_stage_selection == 'data_completion') else ['data_completion']
                        ),
                        ('project_stage_selection', 'not in',
                            ['detailed_study_analyst', 'detailed_study_approval']
                            if (project_path == 'standard' and not is_assign_detailed_study)
                            else (['analyst', 'study_approval'] if project_path == 'specialized' else [])
                        ),
                        ('project_stage_selection', 'not in',
                            ['auctions_manager_decision']
                            if (committee_decision == 'direct_sale' or (committee_decision == 'exclusion' and customer_intent == 'direct_sale'))
                            else (['sales_manager_decision']
                                if (committee_decision == 'auction' or (committee_decision == 'exclusion' and customer_intent == 'auction'))
                                else [])
                        ),
                        '|', ('request_type_ids', '=', False), ('request_type_ids', '=', request_type_id),
                    ]
